style.css:
@-moz-document domain("roblox.com") {
.ad,
.ad *,
.img_ad,
.ad-annotations,
#google_image_div,
#aw0,
#AdvertisingLeaderboard
{
    display: none !important;
}

#header
{
    background-color: #fdcae1 !important;
}

.navigation .notification-icon,
.rbx-highlight
{
    background: #caf5fd !important;
}

#chat-header
{
    background: #ffe1ee !important;
}

.slide-item-container-left,
.profile-avatar-right
{
    background: #caf5fd !important;
}

.rbx-tabs-horizontal .rbx-tab.active .rbx-tab-heading,
.rbx-tabs-horizontal .rbx-tab-heading:hover,
.rbx-tabs-horizontal .rbx-tab-heading:focus,
.rbx-tabs-horizontal .rbx-tab-heading:active
{
    box-shadow: 0 -4px 0 #fdcae1 inset !important;
}

.forum-table-header,
body .forum-table-header th,
body .forum-table-footer,
#ctl00_cphRoblox_Message1_ctl00_CenterColumn > table > tbody > tr:nth-child(1) > th,
#ctl00_cphRoblox_CenterColumn > table > tbody > tr:nth-child(1) > th
{
    background: #caf5fd !important;
}

.rbx-upgrade-now #upgrade-now-button,
.rbx-btn-secondary-xs.btn-more,
#AjaxCommentsContainer > div > div.comment-form > form > button,
.rbx-vip-server-create,
.btn-secondary-xs
{
    background-color: #fdcae1 !important;
    border-color: #ffe1ee !important;
    color: white !important;
}

.rbx-upgrade-now #upgrade-now-button:hover,
.rbx-btn-secondary-xs.btn-more:hover,
#AjaxCommentsContainer > div > div.comment-form > form > button:hover,
.rbx-vip-server-create:hover,
.btn-secondary-xs:hover
{
    background: #ffe1ee !important;
    border-color: #caf5fd !important;
}

#TopAbpContainer,
.ad-annotations,
#LeftGutterAdContainer,
#RightGutterAdContainer,
#Skyscraper-Adp-Right,
#Skyscraper-Adp-Left,
.abp-spacer,
.sponsored-game,
.alert-info,
#mCSB_1_container > ul > li.font-bold.small,
#mCSB_1_container > ul > li.rbx-nav-sponsor
{
    display: none !important;
}

#navbar-search-input,
#navbar-search-btn
{
    border: 1px solid #caf5fd !important;
}

body
{
    background: #ffe1ee !important;
}

.content
{
    background: transparent !important;
}

#fb-root
{
    width: 100% !important;
    height: 100% !important;
    position: fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
}

#party_none_title,
div.friend_dock_chatbox_titlebar.chat-header-blink-off
{
    background: linear-gradient(to bottom, #fdcae1, #caf5fd) !important;
}

#ctl00_cphRoblox_RightColumn,
#Body > table > tbody > tr > td:nth-child(3),
#Body > table > tbody > tr > td:nth-child(4)
{
    display: none !important;
}

#GamesPageLeftColumn
{
    width: auto !important;
    margin-right: 10px !important;
    margin-left: 10px !important;
}

#GamesListsContainer > div
{
    background-color: transparent !important;
    width: 100% !important;
}

#navigation
{
    background-color: #caf5fd !important;
}

.rbx-btn-primary-lg
{
    background-color: #fdcae1 !important;
    border-color: #fdcae1 !important;
}

.rbx-btn-primary-lg:hover,
.rbx-btn-primary-lg:focus
{
    background-color: #ffe1ee !important;
    border-color: #caf5fd !important;
}

/* THUMBNAILS */

.thumbnail-holder-position .thumbnail-2d-container img,
.thumbnail-holder-position .thumbnail-3d-container canvas
{
    object-fit: contain !important;
    box-sizing: border-box !important;

    background: linear-gradient(
        135deg,
        #fdcae1,
        #ffe1ee,
        #caf5fd
    ) !important;

    border: 3px solid #fdcae1 !important;
    border-radius: 14px !important;

    padding: 4px !important;

    box-shadow:
        0 0 10px #fdcae1,
        0 0 18px #caf5fd !important;

    transition: all 0.3s ease !important;
}

.thumbnail-holder-position .thumbnail-2d-container img:hover,
.thumbnail-holder-position .thumbnail-3d-container canvas:hover
{
    border-color: #caf5fd !important;

    box-shadow:
        0 0 14px #ffe1ee,
        0 0 24px #caf5fd !important;

    transform: scale(1.02) !important;
}

/* SEPARATORS */

[role="separator"],
div[role="separator"]
{
    width: 3px !important;
    min-width: 3px !important;
    height: 100% !important;

    border: none !important;

    background: linear-gradient(
        to bottom,
        #fdcae1 0%,
        #ffe1ee 50%,
        #caf5fd 100%
    ) !important;

    box-shadow:
        0 0 8px #fdcae1,
        0 0 16px #caf5fd !important;

    border-radius: 999px !important;

    opacity: 1 !important;

    transition: all 0.3s ease !important;
}

[role="separator"]:hover,
div[role="separator"]:hover
{
    background: linear-gradient(
        to bottom,
        #caf5fd 0%,
        #ffe1ee 50%,
        #fdcae1 100%
    ) !important;

    box-shadow:
        0 0 12px #fdcae1,
        0 0 22px #caf5fd !important;
}
}
